pub static ACTIONS: LazyLock<Value> = LazyLock::new(|| {
    serde_json::from_str(r#"[{"name":"qa.acceptance.run","description":"QA: persistent acceptance dispatch. Composes dev.acceptance.run and writes qa_runs + qa_run_results rows (audit trail; query QA history per contract without re-running).","owner_agent":"qa","steps_json":"[{\"skill\":\"qa-acceptance-run\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"qa.contract.review","description":"QA #1 (shift-left): the thinking gate that reviews a contract BEFORE DEV. Reads goal + briefing + acceptance + the literal microtask patches and decides pass|fail (coverage, snippet sanity, scope, sufficiency). Fail → route to tl.refine.microtasks; pass → MAN/sandbox/DEV proceed. Writes a contract_qa_reviews row. Thinking complement to the deterministic dev.build.gate. In mode=plan it runs SECOND (advisory) — the separate deterministic qa.contract.plan.coverage action gates the static acceptances and drives the re-plan loop first; this AI pass adds open-ended judgment and can still escalate a CONTRACT-level impossibility.","owner_agent":"qa","steps_json":"[{\"skill\":\"qa-contract-review\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"qa.contract.plan.coverage","description":"FIX-PLAN-QA-SPLIT: DETERMINISTIC plan-coverage gate. For each STATIC acceptance (file-exists, grep-in-a-test-command) checks the plan covers it — a microtask targets the file, and a grep target spec states the literal pattern. Dynamic acceptances (build/test commands) are deferred to build+verify. Exhaustive, no false blockers, converges the re-plan loop in one round. input: {contract_slug} | {acceptance, microtasks}. Returns {passed, issues, checked_static, deferred}. Read-only.","owner_agent":"qa","steps_json":"[{\"skill\":\"qa-plan-coverage\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"qa.swarm.coverage","description":"EPIC-SWARM: DETERMINISTIC grep-acceptance coverage gate for the swarm path. Matches each grep/test acceptance against the authored swarm_blocks.content (file-exists is left to the manifest + composition-check). Records a contract_qa_reviews verdict (review_mode=swarm-coverage); the sign gate requires it GREEN, a RED routes back to swarm.author.blocks. Flag-gated. input: {contract_slug}.","owner_agent":"qa","steps_json":"[{\"skill\":\"qa-swarm-coverage\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"qa.scope.check","description":"QA: git diff between contract.base_sha and HEAD must stay inside contract.files_touched. Returns {passed, offenders[]}.","owner_agent":"qa","steps_json":"[{\"skill\":\"qa-scope-check\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"qa.gate.contract.verify","description":"QA canonical gate: composes qa.scope.check + dev.acceptance.run. Pass → contract.status advances impl→done. Fail → status unchanged, system.learn.insight fires.","owner_agent":"qa","steps_json":"[{\"skill\":\"qa-gate-contract-verify\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"qa.sandbox.promote","description":"On QA pass with a sandbox, atomically replace originals with sandbox versions. Tamper detection via captured shas; stage-then-rename for atomicity per file. Wipes the sandbox after success.","owner_agent":"qa","steps_json":"[{\"skill\":\"qa-sandbox-promote\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"qa.sandbox.reset","description":"Wipe a contract sandbox folder + clear sandbox_path. Used when DEV needs to start over. Optionally writes a correction memory with the reset reason.","owner_agent":"qa","steps_json":"[{\"skill\":\"qa-sandbox-reset\",\"input\":\"$.input\",\"as\":\"result\"}]","returns":"$.results.result","on_failure":"abort"},{"name":"qa.review.run","description":"Pure-deterministic code review: 4 scanners (symbol-existence, type-bypass, placeholder-sentinel, security-scan) across given files. No AI.","owner_agent":"qa","steps_json":"[{\"skill\":\"qa-review-scanners\",\"input\":\"$.input\",\"as\":\"review\"}]","returns":"$.results.review","on_failure":"abort"},{"name":"qa.file.read","description":"QA: read a project file (safety guards same as dev.file.read). Read-only, no audit.","owner_agent":"qa","steps_json":"[{\"skill\":\"file-read\",\"input\":\"$.input\",\"as\":\"file\"}]","returns":"$.results.file","on_failure":"abort"},{"name":"qa.audit.verify","description":"QA: verify the sacred_timeline Merkle chain. Returns { valid, count, brokenAt?, reason? }.","owner_agent":"qa","steps_json":"[{\"skill\":\"verify-chain\",\"input\":\"$.input\",\"as\":\"chain\"}]","returns":"$.results.chain","on_failure":"abort"},{"name":"qa.proc.run","description":"QA: run an allowlisted inspection command (same set as dev.proc.run). Read-only audit support.","owner_agent":"qa","steps_json":"[{\"skill\":\"proc-run\",\"input\":\"$.input\",\"as\":\"proc\"}]","returns":"$.results.proc","on_failure":"abort"},{"name":"qa.file.list","description":"QA: list a project directory (safety guards same as dev.file.list). Read-only, no audit.","owner_agent":"qa","steps_json":"[{\"skill\":\"file-list\",\"input\":\"$.input\",\"as\":\"list\"}]","returns":"$.results.list","on_failure":"abort"}]"#).expect("ACTIONS: embedded JSON is valid by construction")
});

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::Value;

    #[test]
    fn actions_parses_with_the_pressed_shape() {
        let v: &Value = &ACTIONS;
        let a = v.as_array().expect("array");
        assert_eq!(a.len(), 13, "pressed length");
        let mut names: Vec<&str> = a.iter().map(|x| x["name"].as_str().expect("name")).collect();
        let n = names.len();
        names.sort(); names.dedup();
        assert_eq!(names.len(), n, "names unique");
    }

}
